def check_function(f_type):
    def f(r):
        if f_type == 'threshold_gt_1':
            return 1 if r > 1 else 0
        else:
            raise ValueError("Unknown function type")

    # Test initial condition: f(11/3) = 1
    if f(11/3) != 1:
        return f"Initial condition failed: f(11/3) = {f(11/3)}"

    # Test functional constraints for small values (optional, but good practice)
    # Test r=2, r'=-2. f(2)+f(-2) = 1+0 = 1. OK.
    # Test r=2, r'=1/2. f(2)+f(1/2) = 1+0 = 1. OK.

    # Calculate the target expression E
    args = [7/3, 11/4, 2024/5, 109/11, 3/71, 5/204]
    result = 0
    for r in args:
        result = (result + f(r)) % 2

    return result

print(check_function('threshold_gt_1'))
